mapper.select:
SELECT *
FROM security_event
WHERE received_at >= #{receivedFrom}
  AND received_at <= #{receivedTo}

    AND event_type = #{query.eventType}


    AND event_category = #{query.eventCategory}


    AND tenant_id = #{query.tenantId}


    AND user_id = #{query.userId}


    AND source_module = #{query.sourceModule}


    AND trace_id = #{query.traceId}


    AND (received_at < #{cursorReceivedAt}
         OR (received_at = #{cursorReceivedAt} AND id < #{cursorId}))

ORDER BY received_at DESC, id DESC
LIMIT #{limit}

SELECT id
FROM security_event
WHERE received_at < #{cutoff}
ORDER BY received_at ASC, id ASC
LIMIT #{limit}

mapper.delete:
DELETE FROM security_event
WHERE id IN

    #{id}
